/*
 * MeOS service worker — push delivery only.
 *
 * Deliberately not a caching layer. An offline cache for an app whose whole
 * job is reading your own data would serve stale memory and hide the fact that
 * it was stale, which is worse than an honest network error. The only reason
 * this file exists is that Web Push cannot be received without one.
 *
 * Hand-rolled rather than generated by next-pwa: the entire behaviour is the
 * eighty lines below, and a build plugin would add a dependency, a build step
 * and a cache strategy nobody asked for.
 *
 * §9.1 is the limit this operates under. A push plays the system notification
 * sound once. It cannot loop, cannot raise the volume, and is silenced by Do
 * Not Disturb and Focus on every platform. The actual *ringing* happens on
 * /alarm/<id>, which is why the notification's only job is to get the user to
 * tap it.
 */

/** Bumped when this file changes, so an old worker is replaced rather than kept. */
const VERSION = "meos-sw-1";

self.addEventListener("install", () => {
  // No cache to warm; take over as soon as the browser allows.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener("push", (event) => {
  if (!event.data) return;

  let payload;
  try {
    payload = event.data.json();
  } catch {
    // A push we cannot parse is not worth a notification the user cannot act
    // on. Swallowing it beats showing "MeOS" with no body.
    return;
  }

  const { title, body, itemId, kind } = payload;
  if (!itemId) return;

  event.waitUntil(
    self.registration.showNotification(title || "Alarm", {
      body: body || "Tap to open MeOS.",
      icon: "/icon-192.png",
      badge: "/icon-192.png",
      /*
       * One tag per alarm, so the escalation *replaces* the previous
       * notification instead of stacking sixteen of them in the shade. The
       * user should find one live alarm, not a pile of history.
       */
      tag: `alarm-${itemId}`,
      renotify: true,
      // Survives until it is acted on; without this some platforms auto-dismiss
      // after a few seconds and the alarm is silently gone.
      requireInteraction: true,
      vibrate: [400, 200, 400, 200, 400],
      data: { itemId, kind: kind || "alarm" },
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();

  const itemId = event.notification.data && event.notification.data.itemId;
  if (!itemId) return;
  const target = `/alarm/${itemId}`;

  /*
   * Focus an open MeOS rather than opening a second one. A user who already
   * has the app open and gets a second window has lost whatever they were
   * typing in the first.
   */
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      for (const client of clients) {
        if ("focus" in client && "navigate" in client) {
          return client.focus().then((focused) => focused.navigate(target));
        }
      }
      return self.clients.openWindow(target);
    }),
  );
});

/*
 * The push service can retire a subscription on its own — a browser update, a
 * long silence, a reinstall. When it does, resubscribing here keeps alarms
 * working without the user noticing anything happened.
 */
self.addEventListener("pushsubscriptionchange", (event) => {
  event.waitUntil(
    (async () => {
      const applicationServerKey =
        (event.oldSubscription && event.oldSubscription.options.applicationServerKey) || null;
      if (!applicationServerKey) return;

      const subscription = await self.registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey,
      });

      await fetch("/api/push/subscribe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ subscription: subscription.toJSON() }),
      });
    })(),
  );
});

// Referenced so a version bump is a real change to the file the browser sees.
self.__MEOS_SW_VERSION = VERSION;
